    values=tuple(params["values"])
    k=int(params["groups"])
    n=len(values)
    total=sum(values)
    def feasible(C):
        groups_needed=1
        cur=0
        for v in values:
            if v>C:
                return False
            if cur+v<=C:
                cur+=v
            else:
                groups_needed+=1
                cur=v
                if groups_needed>k:
                    return False
        return groups_needed<=k
    lo=max(values)
    hi=total
    while lo<hi:
        mid=(lo+hi)//2
        if feasible(mid):
            hi=mid
        else:
            lo=mid+1
    answer=lo
    lower_bound=max(max(values), (total + k - 1)//k)
    return {"answer": answer, "steps": {"total_workload": total, "lower_bound": lower_bound, "minimal_largest_group_total": answer}}

