def solve(params):
    values=params["values"]
    k=params["groups"]
    n=len(values)
    total=sum(values)
    mx=max(values)
    if k>=n:
        return int(mx)
    if k==1:
        return int(total)
    def feasible_linear(arr, C, k):
        need=1
        cur=0
        for v in arr:
            if v>C:
                return False
            if cur+v<=C:
                cur+=v
            else:
                need+=1
                cur=v
                if need>k:
                    return False
        return need<=k
    def feasible_circular(C):
        if mx>C:
            return False
        # try every possible starting point; if any linearization can be packed into <=k groups with capacity C, circle is feasible
        # we need exactly k groups, but packing into <=k is equivalent since we can split groups further without increasing max (values positive)
        for s in range(n):
            arr=[values[(s+i)%n] for i in range(n)]
            if feasible_linear(arr, C, k):
                return True
        return False
    lo=mx
    hi=total
    while lo<hi:
        mid=(lo+hi)//2
        if feasible_circular(mid):
            hi=mid
        else:
            lo=mid+1
    return int(lo)

