def solve(params):
    import itertools
    values=params["values"]
    k=params["groups"]
    n=len(values)
    if k>=n:
        return max(values)
    if k==1:
        return sum(values)
    best=float('inf')
    # circular partitions correspond to choosing k cut positions among n edges
    # enumerate all assignments via cut masks; for n <= 7 this is exhaustive via brute force over partitions of duplicated linearizations
    for start in range(n):
        lin=[values[(start+i)%n] for i in range(n)]
        # choose k-1 cut positions among 1..n-1 to define groups in this linearization
        for cuts in itertools.combinations(range(1,n), k-1):
            prev=0
            cur_max=0
            for c in list(cuts)+[n]:
                s=sum(lin[prev:c])
                if s>cur_max:
                    cur_max=s
                prev=c
            if cur_max<best:
                best=cur_max
    return int(best)
